const String inventoryMobilePageHtml = r'''<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
  <meta name="theme-color" content="#386641">
  <title>JamooManager 端末画面</title>
  <style>
    :root{color-scheme:light;--green:#386641;--green2:#6a994e;--pale:#f3f8ef;--card:#fff;--line:#d8e2d2;--red:#b3261e;--redbg:#ffdad6;--text:#1f2a1f;--muted:#647064}
    *{box-sizing:border-box}body{margin:0;background:var(--pale);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP",sans-serif}
    button,input,select,textarea{font:inherit}button{cursor:pointer}.hidden{display:none!important}
    header{position:sticky;top:0;z-index:5;background:#edf5e8eF;backdrop-filter:blur(10px);border-bottom:1px solid var(--line);padding:12px 14px}
    .head{max-width:900px;margin:auto;display:flex;align-items:center;gap:10px}.title{font-weight:800;font-size:19px;flex:1}.facility{font-size:12px;color:var(--muted)}
    main{max-width:900px;margin:auto;padding:14px 14px 90px}.search{display:flex;gap:8px;margin-bottom:12px}.search input{flex:1}.scan-btn{min-width:94px}
    input,select,textarea{width:100%;border:1px solid #849181;background:white;border-radius:11px;padding:12px;color:var(--text)}
    .btn{border:0;border-radius:999px;padding:10px 15px;background:var(--green);color:white;font-weight:700;white-space:nowrap}.btn.light{background:#dcefd7;color:#24512e}.btn.outline{background:white;color:var(--green);border:1px solid var(--green)}.btn.danger{background:var(--redbg);color:var(--red)}
    .summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}.sum{background:#e2e8df;border-radius:14px;padding:12px}.sum small{display:block;color:var(--muted)}.sum strong{font-size:21px}
    .items{display:grid;gap:10px}.item{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:14px;box-shadow:0 1px 2px #0000000b}.item.low{border-color:#e7a7a1}
    .item-top{display:flex;gap:10px;align-items:flex-start}.item-name{font-size:17px;font-weight:800;flex:1}.category{font-size:12px;color:var(--muted);margin-top:2px}.stock{text-align:right}.stock strong{display:block;font-size:22px}.low .stock strong{color:var(--red)}
    .prices{display:flex;gap:16px;color:var(--muted);font-size:13px;margin:10px 0}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions .btn{flex:1;min-width:90px;padding:9px 10px}
    .empty{text-align:center;background:white;border:1px solid var(--line);padding:32px;border-radius:16px;color:var(--muted)}
    .overlay{position:fixed;inset:0;z-index:20;background:#17201799;display:flex;align-items:flex-end;justify-content:center}.panel{width:100%;max-width:600px;max-height:92vh;overflow:auto;background:var(--pale);border-radius:22px 22px 0 0;padding:20px}.panel h2{margin:0 0 14px}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:700;margin:0 0 5px}.panel-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.panel-actions .btn{min-width:110px}
    .login{align-items:center}.login .panel{border-radius:22px;max-width:420px}.code{font-size:24px;letter-spacing:5px;text-align:center;font-weight:800}.help{font-size:13px;color:var(--muted);line-height:1.6}
    .toast{position:fixed;left:50%;bottom:22px;z-index:40;transform:translateX(-50%);background:#243124;color:white;padding:11px 18px;border-radius:999px;box-shadow:0 4px 18px #0003;max-width:90%;text-align:center}
    .error{background:var(--redbg);color:var(--red);border-radius:11px;padding:10px;margin:10px 0}.spinner{padding:35px;text-align:center;color:var(--muted)}
    .scan-video{width:100%;max-height:45vh;background:#111;border-radius:14px;object-fit:cover}.scan-box{border:1px dashed var(--green);border-radius:14px;padding:12px;margin:12px 0}.scan-row{display:flex;gap:8px;flex-wrap:wrap}.scan-row input{flex:1}.file-label{display:block;text-align:center;margin:10px 0}.scan-status{min-height:24px;font-weight:700;color:var(--green)}
    .tabs{display:flex;gap:6px;margin-right:4px}.tab{border:1px solid var(--green);border-radius:999px;padding:8px 11px;background:white;color:var(--green);font-weight:700}.tab.active{background:var(--green);color:white}
    .calendar-head{display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:12px}.calendar-head strong{font-size:21px;min-width:140px;text-align:center}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-left:1px solid var(--line);border-top:1px solid var(--line);background:white}.weekday,.calendar-day{border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.weekday{text-align:center;padding:7px 2px;font-size:12px;font-weight:700;background:#e7efe3}.weekday.sun{color:#b3261e}.weekday.sat{color:#2864a8}.calendar-day{min-height:88px;padding:6px;background:white;text-align:left;color:var(--text);border-radius:0}.calendar-day.outside{background:#f3f3f0;color:#9a9f99}.calendar-day.selected{outline:3px solid var(--green);outline-offset:-3px;background:#edf7e9}.calendar-day.today .day-number{background:var(--green);color:white}.day-number{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;font-weight:800}.day-stats{margin-top:5px;font-size:11px;line-height:1.45}.day-stats b{display:block;color:var(--green)}.day-stats .arrival{color:#a65300}.day-stats .departure{color:#3c5f9b}.calendar-details{margin-top:16px}.calendar-details h2{font-size:19px}.reservation-card{background:white;border:1px solid var(--line);border-radius:15px;padding:13px;margin-bottom:9px}.reservation-top{display:flex;gap:8px;align-items:flex-start}.reservation-name{font-weight:800;font-size:16px;flex:1}.status-badge{border-radius:999px;padding:4px 8px;background:#dcefd7;color:#24512e;font-size:12px;font-weight:700}.status-badge.arrival{background:#ffe3c5;color:#8c4500}.status-badge.departure{background:#dce7fa;color:#294e87}.reservation-meta{font-size:13px;line-height:1.65;color:var(--muted);margin-top:7px}.calendar-legend{font-size:12px;color:var(--muted);margin:8px 0 12px}
    @media(max-width:700px){header{padding:9px 8px}.head{gap:6px;flex-wrap:wrap}.head>div:first-child{width:100%}.tabs{flex:1}.tab{flex:1;padding:8px 6px}.head>.btn{padding:8px 9px}.calendar-day{min-height:68px;padding:3px}.day-number{width:22px;height:22px;font-size:12px}.day-stats{font-size:9px}.day-stats .rooms{display:none}}
    @media(max-width:560px){.summary{grid-template-columns:repeat(2,1fr)}.sum:last-child{grid-column:span 2}.prices{gap:10px}.actions .btn{min-width:72px}.facility{display:none}}
  </style>
</head>
<body>
  <header><div class="head"><div><div id="pageTitle" class="title">在庫・販売</div><div id="facility" class="facility">JamooManager</div></div><div class="tabs"><button id="inventoryTab" class="tab active">在庫</button><button id="calendarTab" class="tab">予約カレンダー</button></div><button id="reload" class="btn light">更新</button><button id="logout" class="btn outline">コード再入力</button></div></header>
  <main id="inventoryView">
    <div class="search"><input id="search" inputmode="search" placeholder="商品名・コード・バーコードで検索"><button id="scan" class="btn scan-btn">読み取り</button><button id="clear" class="btn light">クリア</button></div>
    <div class="summary"><div class="sum"><small>登録商品</small><strong id="itemCount">0件</strong></div><div class="sum"><small>在庫不足</small><strong id="lowCount">0件</strong></div><div class="sum"><small>表示中</small><strong id="shownCount">0件</strong></div></div>
    <div id="content" class="spinner">接続しています…</div>
  </main>
  <main id="calendarView" class="hidden">
    <div class="calendar-head"><button id="previousMonth" class="btn light" aria-label="前月">‹</button><strong id="calendarMonth"></strong><button id="nextMonth" class="btn light" aria-label="翌月">›</button><button id="todayMonth" class="btn outline">今月</button></div>
    <div class="calendar-legend">日付を押すと、その日のチェックイン・連泊・チェックアウトを表示します。</div>
    <div id="calendarContent" class="spinner">読み込み中…</div>
    <section class="calendar-details"><h2 id="selectedDateTitle"></h2><div id="selectedDateReservations"></div></section>
  </main>

  <div id="login" class="overlay login hidden"><div class="panel"><h2>接続コード</h2><p class="help">Windows版JamooManagerの「端末接続」に表示された8桁のコードを入力してください。</p><input id="token" class="code" inputmode="numeric" maxlength="8" autocomplete="one-time-code" placeholder="00000000"><div id="loginError" class="error hidden"></div><div class="panel-actions"><button id="connect" class="btn">接続</button></div></div></div>

  <div id="movement" class="overlay hidden"><div class="panel"><h2 id="movementTitle">入出庫・販売</h2><div id="movementStock" class="help"></div><div class="field"><label for="type">処理</label><select id="type"><option value="sale">販売</option><option value="purchase">入荷</option><option value="internal_use">館内使用</option><option value="waste">廃棄</option><option value="return_to_stock">返品・在庫戻し</option><option value="adjustment">棚卸調整</option></select></div><div class="field"><label id="quantityLabel" for="quantity">数量</label><input id="quantity" inputmode="decimal" value="1"></div><div class="field"><label for="price">単価（円・任意）</label><input id="price" inputmode="numeric"></div><div class="field"><label for="note">備考（任意）</label><textarea id="note" rows="2"></textarea></div><div id="movementError" class="error hidden"></div><div class="panel-actions"><button id="cancelMovement" class="btn outline">キャンセル</button><button id="saveMovement" class="btn">記録</button></div></div></div>

  <div id="scanner" class="overlay hidden"><div class="panel"><h2>バーコード読み取り</h2><p class="help">商品のJAN・EAN・UPC・Code・QRを読み取ります。USBリーダーは下の欄にカーソルを置いて読み取ってください。</p><video id="scanVideo" class="scan-video hidden" playsinline muted></video><div id="scanStatus" class="scan-status"></div><label class="btn light file-label" for="scanPhoto">カメラで撮影・写真を選択</label><input id="scanPhoto" class="hidden" type="file" accept="image/*" capture="environment"><div class="scan-box"><label for="scanCode">番号入力・USBバーコードリーダー</label><div class="scan-row"><input id="scanCode" inputmode="numeric" autocomplete="off" placeholder="バーコード番号"><button id="useScanCode" class="btn">検索</button><button id="registerScanCode" class="btn light" style="flex-basis:100%;width:100%;margin-top:8px">この番号で新商品登録</button></div></div><div id="scanError" class="error hidden"></div><div class="panel-actions"><button id="cancelScan" class="btn outline">閉じる</button></div></div></div>

  <div id="assignBarcode" class="overlay hidden"><div class="panel"><h2>未登録のバーコード</h2><p id="unknownBarcode" class="help"></p><div class="field"><label for="assignItem">紐付ける既存商品</label><select id="assignItem"></select></div><div id="assignError" class="error hidden"></div><div class="panel-actions"><button id="cancelAssign" class="btn outline">キャンセル</button><button id="newFromBarcode" class="btn light">新しい商品として登録</button><button id="saveAssign" class="btn">既存商品に紐付け</button></div></div></div>

  <div id="newItem" class="overlay hidden"><div class="panel"><h2>バーコードから商品登録</h2><p id="newItemBarcode" class="help"></p><div class="field"><label for="newName">商品名 *</label><input id="newName" autocomplete="off"></div><div class="field"><label for="newCategory">分類 *</label><input id="newCategory" value="食品" autocomplete="off"></div><div class="field"><label for="newUnit">単位 *</label><input id="newUnit" value="個" autocomplete="off"></div><div class="field"><label for="newStock">初期在庫</label><input id="newStock" inputmode="decimal" value="0"></div><div class="field"><label for="newReorder">最低在庫</label><input id="newReorder" inputmode="decimal" value="0"></div><div class="field"><label for="newCost">仕入単価（円・任意）</label><input id="newCost" inputmode="numeric"></div><div class="field"><label for="newSale">販売価格（円・任意）</label><input id="newSale" inputmode="numeric"></div><div class="field"><label for="newSupplier">仕入先（任意）</label><input id="newSupplier" autocomplete="off"></div><div id="newItemError" class="error hidden"></div><div class="panel-actions"><button id="cancelNewItem" class="btn outline">キャンセル</button><button id="saveNewItem" class="btn">商品を登録</button></div></div></div>

  <div id="toast" class="toast hidden"></div>
  <script>
    const now=new Date();
    const state={token:localStorage.getItem('jamoo_inventory_token')||'',items:[],selected:null,loading:false,view:'inventory',calendarMonth:new Date(now.getFullYear(),now.getMonth(),1),selectedDate:new Date(now.getFullYear(),now.getMonth(),now.getDate()),reservations:[],calendarLoading:false};
    const el=id=>document.getElementById(id);
    const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const qty=value=>Number.isInteger(Number(value))?String(Number(value)):Number(value).toFixed(3).replace(/\.?0+$/,'');
    const yen=value=>value==null?'－':'¥'+Number(value).toLocaleString('ja-JP');
    const uuid=()=>globalThis.crypto?.randomUUID?.()||'mobile-'+Date.now()+'-'+Math.random().toString(16).slice(2);
    function normalizeNumber(value){return String(value??'').trim().replace(/[０-９]/g,c=>String.fromCharCode(c.charCodeAt(0)-0xFEE0)).replace(/．/g,'.').replace(/－/g,'-').replace(/[，,\s¥￥円]/g,'')}
    function readNumber(value,{empty=null}={}){const text=normalizeNumber(value);if(text==='')return empty;const number=Number(text);return Number.isFinite(number)?number:NaN}

    async function api(path,options={}){
      const headers={'X-Jamoo-Token':state.token,...(options.headers||{})};
      if(options.body)headers['Content-Type']='application/json';
      const response=await fetch(path,{...options,headers});
      let data={};try{data=await response.json()}catch(_){data={error:'応答を読み込めませんでした。'}}
      if(response.status===401){showLogin('接続コードを確認してください。');throw new Error(data.error||'認証できませんでした。')}
      if(!response.ok)throw new Error(data.error||'処理に失敗しました。');return data;
    }
    function showLogin(message=''){el('loginError').textContent=message;el('loginError').classList.toggle('hidden',!message);el('login').classList.remove('hidden');setTimeout(()=>el('token').focus(),50)}
    function hideLogin(){el('login').classList.add('hidden');el('loginError').classList.add('hidden')}
    function toast(message){el('toast').textContent=message;el('toast').classList.remove('hidden');setTimeout(()=>el('toast').classList.add('hidden'),2400)}
    async function connect(){const token=el('token').value.trim();if(!/^\d{8}$/.test(token)){showLogin('8桁の数字を入力してください。');return}state.token=token;try{const health=await api('/api/v1/health');localStorage.setItem('jamoo_inventory_token',token);el('facility').textContent=health.facilityName||'JamooManager';hideLogin();await refreshActive()}catch(error){showLogin(error.message)}}
    async function loadItems(silent=false){if(state.loading||!state.token)return;state.loading=true;if(!silent){el('content').className='spinner';el('content').textContent='読み込み中…'}try{const health=await api('/api/v1/health');el('facility').textContent=health.facilityName||'JamooManager';const data=await api('/api/v1/inventory/items');state.items=data.items||[];render()}catch(error){if(!state.token)return;if(!silent||!state.items.length){el('content').className='error';el('content').textContent='接続が切れています。Windows版で「端末接続」を開き、この画面を更新してください。'}}finally{state.loading=false}}
    function render(){const term=el('search').value.trim().toLowerCase();const items=state.items.filter(item=>[item.name,item.category,item.sku,item.barcode].some(value=>String(value||'').toLowerCase().includes(term)));el('itemCount').textContent=state.items.length+'件';el('lowCount').textContent=state.items.filter(item=>Number(item.currentStock)<=Number(item.reorderLevel)).length+'件';el('shownCount').textContent=items.length+'件';if(!items.length){el('content').className='empty';el('content').textContent='該当する商品がありません。';return}el('content').className='items';el('content').innerHTML=items.map(item=>{const low=Number(item.currentStock)<=Number(item.reorderLevel);return `<article class="item ${low?'low':''}"><div class="item-top"><div class="item-name">${escapeHtml(item.name)}<div class="category">${escapeHtml(item.category)}${item.barcode?' ・ '+escapeHtml(item.barcode):''}</div></div><div class="stock"><strong>${qty(item.currentStock)} ${escapeHtml(item.unit)}</strong><small>最低 ${qty(item.reorderLevel)} ${escapeHtml(item.unit)}</small></div></div><div class="prices"><span>販売 ${yen(item.salePriceYen)}</span><span>仕入 ${yen(item.costPriceYen)}</span></div><div class="actions">${item.saleEnabled?`<button class="btn" data-key="${escapeHtml(item.syncKey)}" data-type="sale">販売</button>`:''}<button class="btn light" data-key="${escapeHtml(item.syncKey)}" data-type="purchase">入荷</button><button class="btn light" data-key="${escapeHtml(item.syncKey)}" data-type="internal_use">館内使用</button><button class="btn outline" data-key="${escapeHtml(item.syncKey)}" data-type="more">その他</button></div></article>`}).join('')}

    function switchView(view){state.view=view;const calendar=view==='calendar';el('inventoryView').classList.toggle('hidden',calendar);el('calendarView').classList.toggle('hidden',!calendar);el('inventoryTab').classList.toggle('active',!calendar);el('calendarTab').classList.toggle('active',calendar);el('pageTitle').textContent=calendar?'予約カレンダー':'在庫・販売';if(calendar)loadCalendar();else loadItems()}
    function dateKey(value){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`}
    function monthKey(value){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}`}
    function parseDate(value){const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value||''));return match?new Date(Number(match[1]),Number(match[2])-1,Number(match[3])):null}
    function sameDate(left,right){return left&&right&&left.getFullYear()===right.getFullYear()&&left.getMonth()===right.getMonth()&&left.getDate()===right.getDate()}
    function reservationState(reservation,date){const checkIn=parseDate(reservation.checkIn),checkOut=parseDate(reservation.checkOut);if(!checkIn||!checkOut)return '';if(sameDate(date,checkIn))return 'arrival';if(sameDate(date,checkOut))return 'departure';return date>checkIn&&date<checkOut?'stay':''}
    function reservationsForDate(date,{includeDeparture=true}={}){return state.reservations.filter(reservation=>{const status=reservationState(reservation,date);return status&& (includeDeparture||status!=='departure')})}
    async function loadCalendar(silent=false){if(state.calendarLoading||!state.token)return;state.calendarLoading=true;el('calendarMonth').textContent=`${state.calendarMonth.getFullYear()}年${state.calendarMonth.getMonth()+1}月`;if(!silent){el('calendarContent').className='spinner';el('calendarContent').textContent='読み込み中…'}try{const data=await api('/api/v1/reservations/calendar?month='+encodeURIComponent(monthKey(state.calendarMonth)));state.reservations=data.reservations||[];renderCalendar()}catch(error){el('calendarContent').className='error';el('calendarContent').textContent=error.message||'予約カレンダーを読み込めません。'}finally{state.calendarLoading=false}}
    function renderCalendar(){const year=state.calendarMonth.getFullYear(),month=state.calendarMonth.getMonth(),first=new Date(year,month,1),start=new Date(year,month,1-first.getDay()),today=new Date();let html='<div class="calendar-grid">'+['日','月','火','水','木','金','土'].map((day,index)=>`<div class="weekday ${index===0?'sun':index===6?'sat':''}">${day}</div>`).join('');for(let index=0;index<42;index++){const date=new Date(start.getFullYear(),start.getMonth(),start.getDate()+index),all=reservationsForDate(date),occupied=all.filter(value=>reservationState(value,date)!=='departure'),arrivals=all.filter(value=>reservationState(value,date)==='arrival').length,departures=all.filter(value=>reservationState(value,date)==='departure').length,rooms=occupied.reduce((sum,value)=>sum+Number(value.roomCount||1),0),outside=date.getMonth()!==month;html+=`<button class="calendar-day ${outside?'outside':''} ${sameDate(date,state.selectedDate)?'selected':''} ${sameDate(date,today)?'today':''}" data-calendar-date="${dateKey(date)}"><span class="day-number">${date.getDate()}</span><div class="day-stats">${occupied.length?`<b>宿泊 ${occupied.length}件</b><span class="rooms">${rooms}室</span>`:''}${arrivals?`<span class="arrival">入 ${arrivals}</span>`:''}${departures?`<span class="departure">出 ${departures}</span>`:''}</div></button>`}html+='</div>';el('calendarContent').className='';el('calendarContent').innerHTML=html;renderSelectedDate()}
    function dailyGuests(reservation,date){const key=dateKey(date),daily=(reservation.dailyGuestCounts||[]).find(value=>value.date===key);if(daily)return {adults:Number(daily.adults||0),children:Number(daily.childrenWithBed||0)+Number(daily.childrenWithoutBed||0),total:Number(daily.adults||0)+Number(daily.childrenWithBed||0)+Number(daily.childrenWithoutBed||0)};const adults=Number(reservation.adults||0),children=Number(reservation.children||0);return {adults,children,total:Number(reservation.totalGuests??adults+children)}}
