    let hardwareReaderBuffer='',hardwareReaderLastKey=0,hardwareReaderTimer=0;
    function hardwareReaderActive(){return !el('scanner').classList.contains('hidden')}
    function submitHardwareReader(){
      const fieldValue=String(el('scanCode').value||'').trim();
      const code=hardwareReaderBuffer.trim()||fieldValue;
      hardwareReaderBuffer='';clearTimeout(hardwareReaderTimer);
      if(code.length<4)return;
      el('scanCode').value=code;
      acceptBarcode(code);
    }
    function handleHardwareReaderKey(event){
      if(!hardwareReaderActive())return;
      const now=Date.now();
      if(event.key==='Enter'||event.key==='Tab'){
        event.preventDefault();event.stopPropagation();submitHardwareReader();return;
      }
      if(event.key.length!==1||event.ctrlKey||event.altKey||event.metaKey)return;
      if(now-hardwareReaderLastKey>180)hardwareReaderBuffer='';
      hardwareReaderLastKey=now;
      hardwareReaderBuffer+=event.key;
      clearTimeout(hardwareReaderTimer);
      hardwareReaderTimer=setTimeout(submitHardwareReader,220);
    }
    document.addEventListener('keydown',handleHardwareReaderKey,true);
    let barcodeInputTimer=0,observedBarcode='',observedBarcodeAt=0,barcodeSubmitting=false;
    function observeBarcodeInput(){
      if(el('scanner').classList.contains('hidden')){observedBarcode='';observedBarcodeAt=0;barcodeSubmitting=false;return}
      const code=String(el('scanCode').value||'').trim();
      if(code.length<4){observedBarcode=code;observedBarcodeAt=Date.now();return}
      if(code!==observedBarcode){observedBarcode=code;observedBarcodeAt=Date.now();return}
      if(!barcodeSubmitting&&observedBarcodeAt&&Date.now()-observedBarcodeAt>=900){
        barcodeSubmitting=true;
        acceptBarcode(code).finally(()=>{barcodeSubmitting=false;observedBarcode='';observedBarcodeAt=0});
      }
    }
